  // 16-tap Vogel spiral with golden ratio rotation produces silky smooth
  // penumbras free of regular lattice banding or directional noise.
  vec2 t=uShadowMapTexelSize*clamp(uShadowFilterRadius,0.,3.);
  // Adaptive contact-hardening: estimate blocker proximity to sharpen contact shadows
  float blockerSum=0.0;
  float blockerCount=0.0;
  for(int b=0;b<4;b++){
    float depthSample=texture(uShadowMap,projCoord.xy+VOGEL_16[b*4]*t*1.5).r;
    if(depthSample<projCoord.z-bias){
      blockerSum+=depthSample;
      blockerCount+=1.0;
    }
  }
  float penumbraScale=1.0;
  if(blockerCount>0.0){
    float avgBlockerDepth=blockerSum/blockerCount;
    float penumbraRatio=clamp((projCoord.z-avgBlockerDepth)/max(projCoord.z,0.0001),0.0,1.0);
    penumbraScale=mix(0.38,1.0,smoothstep(0.0002,0.012,penumbraRatio));
  }
  vec2 filterRadius=t*penumbraScale;
  float sum=0.;
  for(int i=0;i<16;i++){
    sum+=sampleShadow(projCoord+vec3(VOGEL_16[i]*filterRadius,0.),bias);
  }
  return sum/16.;
}

void main(){
  // The divide that undoes the rasterizer's own perspective correction (see
  // shadowed_world.vert). Branched on the uniform rather than always
  // dividing, so a zero-strength draw samples the untouched vUv and is
  // bit-identical to the pre-affine path — the divisor is 1.0 there, but
  // only after an interpolate/divide round-trip that need not return
  // exactly 1.0. The branch is uniform across the whole draw, so it costs
  // no divergence.
  vec2 uv=uAffineWarpStrength>0.?vUv/vUvW:vUv;
  uv=uv*uUvScaleOffset.xy+uUvScaleOffset.zw;
  vec4 tex=texture(uAlbedo,uv);
  // fragment must not pay for four shadow-map taps and two normalizes it
  // will never use. uAlphaCutoff==0 is the pass's "this material has no
  // cutout" sentinel (MaterialDefinition.validate forbids a real zero), so
  // opaque and blended draws take a path containing no alpha compare at
  // all rather than one comparing against an unreachable threshold. The
  // same test, against the same uv, runs in depth_prepass.frag and
  // shadow_caster.frag — three passes must agree on which fragments exist
  // or SSAO, DOF and shadowing all occlude against holes this pass shaded
  // through.
  if(uAlphaCutoff>0.&&tex.a<uAlphaCutoff)discard;
  vec3 n=normalize(vNormal);
  // Surface-v2 supplies a tangent4 with OpenGL's +/-1 handedness in W.
  // Compatibility14 meshes leave the attribute at its default zero and use
  // the derivative frame below, so old content and authored tangents share
  // one shader contract.
  if(uNormalStrength>0.0){
    vec3 dp1=dFdx(vWorldPos),dp2=dFdy(vWorldPos);
    vec2 duv1=dFdx(uv),duv2=dFdy(uv);
    vec3 derivativeT=normalize(dp1*duv2.y-dp2*duv1.y);
    vec3 derivativeB=normalize(-dp1*duv2.x+dp2*duv1.x);
    vec3 authoredT=normalize(vTangent.xyz-n*dot(n,vTangent.xyz));
    bool hasAuthoredT=dot(vTangent.xyz,vTangent.xyz)>0.25;
    vec3 t=hasAuthoredT?authoredT:derivativeT;
    vec3 b=hasAuthoredT?normalize(cross(n,t)*vTangent.w):derivativeB;
    vec3 map=texture(uNormalMap,uv).xyz*2.0-1.0;
    map.xy*=uNormalStrength;
    n=normalize(mat3(t,b,n)*normalize(map));
  }
  // A double-sided surface seen from behind is the same sheet facing the
  // other way: negate the finished (normal-mapped) front normal, so a bump
  // on the front reads as a dent from behind. Single-sided materials cull
  // back faces, so this only affects double-sided ones.
  if(!gl_FrontFacing) n=-n;
  vec3 orm=texture(uOrmMap,uv).rgb;
  float normalVariance=0.0;
  if(uNormalStrength>0.0){
    // Toksvig-style widening suppresses sub-pixel normal sparkle when a high
    // resolution map is minified. It preserves authored relief at distance
    // while converting unresolved detail into a stable roughness increase.
    vec3 normalSample=texture(uNormalMap,uv).xyz*2.0-1.0;
    vec3 normalDx=dFdx(normalSample);
    vec3 normalDy=dFdy(normalSample);
    normalVariance=dot(normalDx,normalDx)+dot(normalDy,normalDy);
  }
  float ao=texture(uSsao,gl_FragCoord.xy/uSceneColorSize).r;
  ao*=mix(1.0,orm.r,clamp(uOcclusionStrength,0.0,1.0));
  vec3 direct=vec3(0.);
  float directionalNdotL=max(dot(n,normalize(uDirectionalDirection)),0.);
  direct+=uDirectionalColor*uDirectionalIntensity*directionalNdotL;
  direct+=pointContribution(n,vWorldPos,uPointPosition0,uPointColor0,
    uPointIntensity0,uPointRadius0);
  direct+=pointContribution(n,vWorldPos,uPointPosition1,uPointColor1,
    uPointIntensity1,uPointRadius1);
  direct+=pointContribution(n,vWorldPos,uPointPosition2,uPointColor2,
    uPointIntensity2,uPointRadius2);
  direct+=pointContribution(n,vWorldPos,uPointPosition3,uPointColor3,
    uPointIntensity3,uPointRadius3);
  direct+=directSpotContribution(n,vWorldPos,uDirectSpotPosition0,
    uDirectSpotDirection0,uDirectSpotColor0,uDirectSpotIntensity0,
    uDirectSpotRange0,uDirectSpotInnerCos0,uDirectSpotOuterCos0,
    uDirectSpotEnabled0);
  direct+=directSpotContribution(n,vWorldPos,uDirectSpotPosition1,
    uDirectSpotDirection1,uDirectSpotColor1,uDirectSpotIntensity1,
    uDirectSpotRange1,uDirectSpotInnerCos1,uDirectSpotOuterCos1,
    uDirectSpotEnabled1);
  direct+=directSpotContribution(n,vWorldPos,uDirectSpotPosition2,
    uDirectSpotDirection2,uDirectSpotColor2,uDirectSpotIntensity2,
    uDirectSpotRange2,uDirectSpotInnerCos2,uDirectSpotOuterCos2,
    uDirectSpotEnabled2);
  vec3 toSpot=normalize(uLightPosition-vWorldPos);
  float spotNdotL=max(dot(n,toSpot),0.);
  float shadow=uReceivesShadow>0.5?shadowFactor(spotNdotL):1.;
  float attenuation=lightAttenuation(vWorldPos);
  direct+=uLightColor*uLightIntensity*spotNdotL*shadow*attenuation*uSpotEnabled;
  direct*=uDirectLightScale;
  // §8.5: "modulates ambient only" — SSAO must never darken the direct
  // (N.L * shadow * attenuation) term, only the ambient fill, or it would
  // double up with real shadowing and read as an incorrect global darkening
  // rather than contact occlusion specifically.
  float upward=clamp(n.y*0.5+0.5,0.0,1.0);
  vec3 ambient=uAmbientColor*uAmbientIntensity*uAmbientLightScale*ao*mix(0.85,1.15,upward);
  vec3 baseColor=vColor.rgb*tex.rgb*uMaterialTint;
  // Metallic surfaces contribute less diffuse energy; roughness keeps a
  // small, stable broadening factor until the surface-v2 camera/specular
  // block lands. Both channels therefore affect the live output rather than
  // being metadata-only fields.
  float metal=clamp(uMetallic*orm.b,0.0,1.0);
  float rough=clamp(uRoughness*orm.g,0.0,1.0);
  // Weather changes the material before direct and environment response.
  // Thawing therefore affects the same specular lobe the viewer sees,
  // instead of changing only diffuse color after the highlight is computed.
  float wetDepth=1.0-smoothstep(2.0,18.0,max(vViewDepth,0.0));
  float wetness=clamp(uRainWetness,0.0,1.0)*wetDepth;
  baseColor=mix(baseColor,baseColor*vec3(0.84,0.90,0.98),wetness*0.22);
  float thermalDissolution=clamp(uSurfaceDissolution,0.0,1.0);
  // A steady spherical conductive field decays approximately as 1/r. The
  // host keeps the slow latent material memory in uSurfaceDissolution; this
  // local term therefore models the spatial heat field without making warm
  // surfaces snap back or disappear at an arbitrary exponential radius.
  if(uThermalSourceCount>0.5) thermalDissolution=max(thermalDissolution,
    uThermalSourceDissolution0*clamp(uThermalSourceRadius0/
      max(distance(vWorldPos,uThermalSourcePosition0),uThermalSourceRadius0),0.,1.));
  if(uThermalSourceCount>1.5) thermalDissolution=max(thermalDissolution,
    uThermalSourceDissolution1*clamp(uThermalSourceRadius1/
      max(distance(vWorldPos,uThermalSourcePosition1),uThermalSourceRadius1),0.,1.));
  if(uThermalSourceCount>2.5) thermalDissolution=max(thermalDissolution,
    uThermalSourceDissolution2*clamp(uThermalSourceRadius2/
      max(distance(vWorldPos,uThermalSourcePosition2),uThermalSourceRadius2),0.,1.));
  if(uThermalSourceCount>3.5) thermalDissolution=max(thermalDissolution,
    uThermalSourceDissolution3*clamp(uThermalSourceRadius3/
      max(distance(vWorldPos,uThermalSourcePosition3),uThermalSourceRadius3),0.,1.));
  thermalDissolution=clamp(thermalDissolution,0.0,1.0);
  float snowCoverage=clamp(uSurfaceSnowCoverage,0.0,1.0)*
    smoothstep(0.18,0.82,upward)*(1.0-thermalDissolution*0.72);
  baseColor=mix(baseColor,vec3(0.78,0.86,0.95),snowCoverage*0.82);
  float dissolution=thermalDissolution;
  baseColor=mix(baseColor,baseColor*vec3(0.82,0.86,0.90),dissolution*0.16);
  rough=mix(rough,max(0.06,rough*0.58),dissolution*0.72);
  // Avoid singular highlights while retaining a visibly sharp porcelain
  // response at the authored low end of the roughness range.
  float specRough=max(0.045,sqrt(rough*rough+normalVariance*0.18));
  // A continuous water film forms a second dielectric lobe. It smooths the
  // authored surface only as coverage rises, so damp cloth stays diffuse
  // while puddled stone gains a tight grazing reflection.
  float waterCoverage=smoothstep(0.20,0.88,wetness)*(1.0-0.35*rough);
  specRough=mix(specRough,max(0.035,specRough*0.18),waterCoverage);
  vec3 viewDir=normalize(uCameraPosition-vWorldPos);
  vec3 specular=vec3(0.0);
  specular+=specularContribution(n,viewDir,normalize(uDirectionalDirection),
    uDirectionalColor,uDirectionalIntensity,1.0,baseColor,specRough,metal);
  specular+=specularContribution(n,viewDir,
    normalize(uPointPosition0-vWorldPos),uPointColor0,uPointIntensity0,
    pointAttenuation(vWorldPos,uPointPosition0,uPointRadius0),baseColor,
    specRough,metal);
  specular+=specularContribution(n,viewDir,
    normalize(uPointPosition1-vWorldPos),uPointColor1,uPointIntensity1,
    pointAttenuation(vWorldPos,uPointPosition1,uPointRadius1),baseColor,
    specRough,metal);
  specular+=specularContribution(n,viewDir,
    normalize(uPointPosition2-vWorldPos),uPointColor2,uPointIntensity2,
    pointAttenuation(vWorldPos,uPointPosition2,uPointRadius2),baseColor,
    specRough,metal);
  specular+=specularContribution(n,viewDir,
    normalize(uPointPosition3-vWorldPos),uPointColor3,uPointIntensity3,
    pointAttenuation(vWorldPos,uPointPosition3,uPointRadius3),baseColor,
    specRough,metal);
  specular+=specularContribution(n,viewDir,
    normalize(uLightPosition-vWorldPos),uLightColor,uLightIntensity,
    lightAttenuation(vWorldPos)*uSpotEnabled*shadow,baseColor,specRough,metal);
  float spotAtten0=directSpotAttenuation(vWorldPos,uDirectSpotPosition0,
    uDirectSpotDirection0,uDirectSpotRange0,uDirectSpotInnerCos0,uDirectSpotOuterCos0,
    uDirectSpotEnabled0);
  if(spotAtten0>0.001){
    specular+=specularContribution(n,viewDir,normalize(uDirectSpotPosition0-vWorldPos),
      uDirectSpotColor0,uDirectSpotIntensity0,spotAtten0,baseColor,specRough,metal);
  }
  float spotAtten1=directSpotAttenuation(vWorldPos,uDirectSpotPosition1,
    uDirectSpotDirection1,uDirectSpotRange1,uDirectSpotInnerCos1,uDirectSpotOuterCos1,
    uDirectSpotEnabled1);
  if(spotAtten1>0.001){
    specular+=specularContribution(n,viewDir,normalize(uDirectSpotPosition1-vWorldPos),
      uDirectSpotColor1,uDirectSpotIntensity1,spotAtten1,baseColor,specRough,metal);
  }
  float spotAtten2=directSpotAttenuation(vWorldPos,uDirectSpotPosition2,
    uDirectSpotDirection2,uDirectSpotRange2,uDirectSpotInnerCos2,uDirectSpotOuterCos2,
    uDirectSpotEnabled2);
  if(spotAtten2>0.001){
    specular+=specularContribution(n,viewDir,normalize(uDirectSpotPosition2-vWorldPos),
      uDirectSpotColor2,uDirectSpotIntensity2,spotAtten2,baseColor,specRough,metal);
  }
  specular*=uDirectLightScale*uSpecularScale;
  // Keep reflected energy available to the specular lobe. The previous
  // diffuse-first clamp clipped bright ceramic response before tone mapping,
  // producing the broad plastic patches visible in low-roughness samples.
  // This split is bounded by the material metalness and lets the final
  // composite perform the intentional HDR compression once.
  vec3 diffuseEnergy=baseColor*(1.0-metal)*
    (ambient+direct*(1.0-0.25*rough));
  vec3 lit=diffuseEnergy+specular;
  // A restrained dielectric clearcoat is intentionally separate from the
  // base roughness/metalness response. It gives porcelain a broad, stable
  // grazing highlight without turning the surface into a mirror.
  vec3 coatLight=normalize(uDirectionalDirection);
  vec3 coatHalf=normalize(viewDir+coatLight);
  float coatNdotV=max(dot(n,viewDir),0.);
  float coatNdotH=max(dot(n,coatHalf),0.);
  float coatNdotL=max(dot(n,coatLight),0.);
  float coatPower=mix(128.0,8.0,clamp(uClearcoatRoughness,0.0,1.0));
  float coatFresnel=0.04+0.96*pow(1.0-coatNdotV,5.0);
  float coatStrength=max(clamp(uClearcoatStrength,0.0,1.0),waterCoverage*0.82);
  float coat=coatStrength*coatFresnel*
    pow(coatNdotH,coatPower)*coatNdotL*uDirectionalIntensity*
    uDirectLightScale*uSpecularScale;
  lit+=uDirectionalColor*coat;
  lit+=direct*(wetness*(0.035+0.075*(1.0-rough)));
  // Environment fallback reflections are deliberately bounded and weighted
  // by wetness/grazing angle. A real probe/history hit can raise confidence;
  // the current host fallback remains visible but never masquerades as SSR.
  float reflectionNdotV=max(dot(n,viewDir),0.0);
  vec3 f0=mix(vec3(0.04),baseColor,metal);
  vec3 envFresnel=f0+(max(vec3(1.0-specRough),f0)-f0)*pow(clamp(1.0-reflectionNdotV,0.0,1.0),5.0);
  float envGloss=(1.0-specRough)*(1.0-specRough);
  float reflectionSurface=clamp(metal*0.85+(1.0-metal)*(wetness+0.18*dissolution+envGloss*0.25),0.0,1.0);
  float reflectionConfidence=0.20+0.80*clamp(uReflectionConfidence,0.0,1.0);
  float reflectionWeight=clamp(
    uReflectionIntensity*reflectionSurface*
      (1.0-0.72*rough)*reflectionConfidence,
    0.0,1.0);
  vec3 reflectDir=reflect(-viewDir,n);
  float refUp=clamp(reflectDir.y*0.5+0.5,0.0,1.0);
  // Ambient radiance is colour × intensity, as in the diffuse term above;
  // the raw colour made dark scenes (night) reflect a bright sky.
  vec3 envAmbient=uAmbientColor*uAmbientIntensity*uAmbientLightScale;
  vec3 envRadiance=mix(envAmbient*0.35,mix(envAmbient,uReflectionColor,refUp),refUp);
  vec3 sunReflectDir=normalize(uDirectionalDirection);
  float sunRdotL=max(dot(reflectDir,sunReflectDir),0.0);
  envRadiance+=uDirectionalColor*pow(sunRdotL,mix(32.0,4.0,specRough))*(1.0-specRough)*0.4;
  lit+=envRadiance*envFresnel*reflectionWeight*ao;
  float backScatter=max(dot(-viewDir,normalize(uDirectionalDirection)),0.0);
  vec3 subsurface=baseColor*uDirectionalColor*(pow(backScatter,4.0)*(1.0-metal)*0.12*uDirectionalIntensity);
  lit+=subsurface;
  vec3 emissive=texture(uEmissiveMap,uv).rgb*uMaterialTint*uEmissiveStrength;
  lit+=emissive;
  if(uLightmapIntensity>0.0){
    lit+=baseColor*texture(uLightmap,vUv1).rgb*uLightmapIntensity;
  }
  if(uLightProbeShEnabled>0.5){
    lit+=baseColor*evaluateLightProbeSh3(n)*ao;
  }
  if(uVertexLightingEnabled>0.5){
    lit+=baseColor*vVertexLighting*ao;
  }
  // Fog blends the surface's own lit color toward uFogColor only — never
  // oGlow below, which stays a declared emissive quantity independent of
  // how much atmosphere sits between the surface and the camera, matching
  // §8.7's "does not infer glow from final luma" scoping: fog is a
  // property of oColor's reflected/lit light, not of emission.
  float fog=fogFactor(vViewDepth,vWorldPos.y);
  vec3 foggedLit=mix(lit,uFogColor,fog);
  // Bug 18: vColor.a*tex.a is the correct alpha for a blended draw and the
  // wrong one for everything else. present.frag copies this channel
  // straight through to a canvas created with the default alpha:true, so an
  // opaque or masked surface that emitted a texel's own alpha would show
  // the *page* through solid geometry. Coverage, not transparency, is what
  // an opaque or masked fragment writes: whatever survived the discard
  // above is fully covering, and an opaque draw always was. uOpaqueCoverage
  // is exactly 0 or 1, so the mix is exact in both directions and the
  // blended path keeps its pre-existing expression bit-for-bit.
  float outAlpha=mix(vColor.a*tex.a,1.,uOpaqueCoverage);
  if(uDebugViewMode==1){oColor=vec4(baseColor,outAlpha);oGlow=vec4(0.0);return;}
  if(uDebugViewMode==2){oColor=vec4(n*0.5+0.5,outAlpha);oGlow=vec4(0.0);return;}
  if(uDebugViewMode==3){oColor=vec4(vec3(rough),outAlpha);oGlow=vec4(0.0);return;}
  if(uDebugViewMode==4){
    float heat=clamp((directionalNdotL+spotNdotL*shadow)*0.5,0.0,1.0);
    vec3 heatColor=mix(vec3(0.0,0.0,1.0),vec3(0.0,1.0,0.0),clamp(heat*2.0,0.0,1.0));
    heatColor=mix(heatColor,vec3(1.0,0.0,0.0),clamp(heat*2.0-1.0,0.0,1.0));
    oColor=vec4(heatColor,outAlpha);oGlow=vec4(0.0);return;
  }
  if(uDebugViewMode==5){oColor=vec4(0.1,0.04,0.02,outAlpha);oGlow=vec4(0.0);return;}
  oColor=vec4(foggedLit,outAlpha);
  // §8.7: bloom reads this declared attachment directly, never inferring
  // glow from oColor's final luma — a bright-but-non-emissive lit surface
  // (e.g. the checkerboard floor under strong light) must never bloom, only
  // a material with real emissiveStrength does, independent of how the
  // surface happens to be lit this frame.
  // Glow carries the same coverage as colour: opaque draws write alpha 1 as
  // before, while blended and additive draws (both blend with srcAlpha)
  // fade their glow with the sprite instead of blooming the whole quad.
  oGlow=vec4(emissive,outAlpha);
}
''';

const String presentVertSrc = '''
#version 300 es
out vec2 vUv;
void main(){
  vec2 p=vec2(float((gl_VertexID<<1)&2),float(gl_VertexID&2));
  vUv=p;
  gl_Position=vec4(p*2.0-1.0,0.0,1.0);
}
''';

const String presentFragSrc = '''
#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D uTex;
uniform float uExposure;
uniform float uVignette;
uniform float uGrain;
uniform float uOutputEncoding;
uniform float uToneMap;
uniform vec3 uClearColor;
uniform vec3 uSkyHorizon;
uniform vec3 uSkyZenith;
uniform vec3 uSkyGround;
uniform float uSkyEnabled;
uniform float uSkyHorizonGlow;
uniform float uSkyStarDensity;
uniform sampler2D uSkyTexture;
uniform float uSkyTextureEnabled;
uniform float uSkyRotation;
uniform float uSkyExposure;
uniform float uSkyTextureSrgb;
uniform mat4 uInverseProjection;
uniform mat4 uInverseView;
uniform vec3 uCameraPosition;
uniform float uCloudCoverage;
uniform float uCloudDensity;
uniform float uCloudBaseHeight;
uniform float uCloudThickness;
uniform float uCloudScale;
uniform vec2 uCloudWind;
uniform float uCloudPhase;
uniform float uCloudDetail;
uniform float uCloudSilverLining;
uniform float uCloudSampleCount;
uniform vec3 uCloudLightDirection;
uniform vec3 uCloudLightColor;
uniform float uCloudLightIntensity;
out vec4 oColor;

float hash(vec2 p){
  return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);
}

vec3 reinhardToneMap(vec3 color){
  return color/(vec3(1.)+color);
}

vec3 acesToneMap(vec3 color){
  return clamp((color*(2.51*color+0.03))/(color*(2.43*color+0.59)+0.14),0.0,1.0);
}

vec3 agxToneMap(vec3 color){
  const mat3 agxMat=mat3(
    0.842479062253094,0.0423282422610123,0.0423756549057051,
    0.0784335999999992,0.878468636469772,0.0784336,
    0.0792237451477643,0.0791661274605434,0.879142973793104
  );
  const mat3 agxMatInv=mat3(
    1.19687902425764,-0.0528968517032958,-0.0529716355080549,
    -0.0980208811401368,1.15190312990417,-0.0980434501171241,
    -0.0990297440797205,-0.0989611768448433,1.15107367264185
  );
  vec3 val=agxMat*color;
  val=clamp(log2(max(val,vec3(1e-10)))*0.0625+0.625,0.0,1.0);
  val=val*val*val*(val*(val*6.0-15.0)+10.0);
  val=agxMatInv*val;
  return pow(max(val,vec3(0.0)),vec3(2.2));
}

vec3 linearToSrgb(vec3 color){
  vec3 cutoff=step(vec3(.0031308),color);
  vec3 low=color*12.92;
  vec3 high=1.055*pow(max(color,vec3(0.)),vec3(1./2.4))-.055;
  return mix(low,high,cutoff);
}

vec3 skyBackground(vec3 direction){
  // A deliberately cheap, high-quality fallback sky: three atmospheric bands
  // provide depth at every camera angle, while the tiny deterministic star
  // field and horizon glow keep the clear background from reading as a flat
  // color. It is an environment layer, not a game/weather simulation.
  //
  // The bands follow the real horizon (the view direction), not the screen.
  // Below the horizon is ground, which a matched horizon makes equal to the
  // fog, so fully fogged geometry and the sky beside it meet without a seam;
  // a screen-space gradient painted zenith colour wherever a downward camera
  // saw past the fog.
  float elevation=clamp(direction.y,-1.,1.);
  vec3 color=mix(uSkyHorizon,uSkyGround,smoothstep(0.0,-0.2,elevation));
  color=mix(color,uSkyZenith,smoothstep(0.0,0.6,elevation));
  float horizonGlow=exp(-pow(elevation*9.0,2.0));
  color+=uSkyHorizon*horizonGlow*clamp(uSkyHorizonGlow,0.,1.);
  // Stars sit on a sky-fixed grid (about two cells per degree), so they stay
  // put as the camera turns. Each lit cell holds one small round star at a
  // jittered spot with its own brightness.
  float starMask=smoothstep(0.04,0.3,elevation);
  vec2 cell=vec2(atan(direction.z,direction.x),asin(elevation))*(360.0/3.14159265359);
  vec2 id=floor(cell);
  float seed=hash(id);
  vec2 offset=vec2(hash(id+vec2(17.0,3.0)),hash(id+vec2(5.0,29.0)))*0.5+0.25;
  float point=1.0-smoothstep(0.08,0.22,length(fract(cell)-offset));
  float stars=step(1.0-clamp(uSkyStarDensity,0.,.1),seed)*point*starMask;
  color+=vec3(0.16,0.19,0.24)*stars*(0.6+0.9*hash(id+vec2(41.0,11.0)));
  return max(color,vec3(0.0));
}

float hash3(vec3 p){
  return fract(sin(dot(p,vec3(127.1,311.7,74.7)))*43758.5453123);
}

float valueNoise(vec3 p){
  vec3 i=floor(p);
  vec3 f=fract(p);
  f=f*f*(3.0-2.0*f);
  float n000=hash3(i+vec3(0,0,0));
  float n100=hash3(i+vec3(1,0,0));
  float n010=hash3(i+vec3(0,1,0));
  float n110=hash3(i+vec3(1,1,0));
  float n001=hash3(i+vec3(0,0,1));
  float n101=hash3(i+vec3(1,0,1));
  float n011=hash3(i+vec3(0,1,1));
  float n111=hash3(i+vec3(1,1,1));
  float x00=mix(n000,n100,f.x);
  float x10=mix(n010,n110,f.x);
  float x01=mix(n001,n101,f.x);
  float x11=mix(n011,n111,f.x);
  return mix(mix(x00,x10,f.y),mix(x01,x11,f.y),f.z);
}

float cloudNoise(vec3 p){
  float value=0.0;
  float amplitude=0.5;
  for(int octave=0;octave<4;octave++){
    value+=valueNoise(p)*amplitude;
    p=p*2.03+vec3(17.3,11.7,7.1);
    amplitude*=0.5;
  }
  return value;
}

float cloudDensityAt(vec3 position){
  float height01=clamp(
    (position.y-uCloudBaseHeight)/max(uCloudThickness,0.001),
    0.0,1.0
  );
  float vertical=smoothstep(0.0,0.12,height01)*
    (1.0-smoothstep(0.72,1.0,height01));
  vec3 q=position*max(uCloudScale,0.00001)+
    vec3(uCloudWind.x*uCloudPhase,0.0,uCloudWind.y*uCloudPhase);
  float macro=cloudNoise(q*0.82);
  float detail=cloudNoise(q*2.7+vec3(23.0,5.0,41.0));
  float shape=mix(macro,macro*0.68+detail*0.32,clamp(uCloudDetail,0.,1.));
  float threshold=1.0-clamp(uCloudCoverage,0.,1.);
  float body=smoothstep(threshold,threshold+0.26,shape);
  return body*vertical*clamp(uCloudDensity,0.,1.);
}

vec4 volumetricClouds(vec3 worldDirection){
  if(uCloudCoverage<=0.0001 || uCloudDensity<=0.0001 || worldDirection.y<=0.001){
    return vec4(0.0);
  }
  float directionY=max(worldDirection.y,0.001);
  float startT=(uCloudBaseHeight-uCameraPosition.y)/directionY;
  float endT=(uCloudBaseHeight+uCloudThickness-uCameraPosition.y)/directionY;
  startT=max(startT,0.0);
  endT=max(endT,0.0);
  if(endT<=startT) return vec4(0.0);
  int sampleCount=int(clamp(uCloudSampleCount,4.,24.));
  float stepLength=(endT-startT)/float(sampleCount);
  float jitter=(hash(gl_FragCoord.xy+vec2(uCloudPhase*0.013))-0.5)*stepLength;
  vec3 sunDirection=normalize(-uCloudLightDirection);
  float transmittance=1.0;
  vec3 inScatter=vec3(0.0);
  for(int i=0;i<24;i++){
    if(i>=sampleCount) break;
    float t=startT+(float(i)+0.5)*stepLength+jitter;
    vec3 position=uCameraPosition+worldDirection*t;
    float density=cloudDensityAt(position);
    float opticalDepth=density*stepLength*0.0035;
    float segmentAlpha=1.0-exp(-opticalDepth);
    float towardLight=cloudDensityAt(position+sunDirection*90.0);
    float lightTransmittance=exp(-towardLight*0.025);
    float phase=0.72+0.28*pow(max(dot(-worldDirection,sunDirection),0.0),2.0);
    vec3 ambient=uSkyHorizon*0.32;
    vec3 direct=uCloudLightColor*
      (0.14+0.86*clamp(uCloudLightIntensity,0.,1.5))*phase;
    float edge=pow(1.0-clamp(density,0.,1.),3.0)*uCloudSilverLining*0.22;
    vec3 sampleLight=(ambient+direct)*lightTransmittance+vec3(edge);
    inScatter+=transmittance*segmentAlpha*sampleLight;
    transmittance*=1.0-segmentAlpha;
    if(transmittance<0.01) break;
  }
  return vec4(inScatter,1.0-transmittance);
}

vec3 srgbToLinear(vec3 color){
  vec3 low=color/12.92;
  vec3 high=pow((color+0.055)/1.055,vec3(2.4));
  return mix(low,high,step(vec3(0.04045),color));
}

vec3 worldDirectionForUv(vec2 uv){
  vec2 ndc=uv*2.0-1.0;
  vec4 viewPoint=uInverseProjection*vec4(ndc,1.0,1.0);
  return normalize(viewPoint.xyz/viewPoint.w);
}

vec3 equirectangularSky(vec2 uv){
  vec3 worldDirection=normalize((uInverseView*vec4(worldDirectionForUv(uv),0.0)).xyz);
  float longitude=atan(worldDirection.z,worldDirection.x)+uSkyRotation;
  float latitude=asin(clamp(worldDirection.y,-1.0,1.0));
  vec2 sampleUv=vec2(
    fract(longitude/(2.0*3.14159265359)+0.5),
    0.5-latitude/3.14159265359
  );
  vec3 encoded=max(texture(uSkyTexture,sampleUv).rgb,vec3(0.0));
  vec3 linear=mix(encoded,srgbToLinear(encoded),clamp(uSkyTextureSrgb,0.,1.));
  return linear*max(uSkyExposure,0.0);
}

vec4 applyFxaa(sampler2D tex, vec2 uv){
  vec2 texelSize=1.0/vec2(textureSize(tex,0));
  vec3 rgbM=texture(tex,uv).rgb;
  vec3 rgbNW=texture(tex,uv+vec2(-texelSize.x,-texelSize.y)).rgb;
  vec3 rgbNE=texture(tex,uv+vec2( texelSize.x,-texelSize.y)).rgb;
  vec3 rgbSW=texture(tex,uv+vec2(-texelSize.x, texelSize.y)).rgb;
  vec3 rgbSE=texture(tex,uv+vec2( texelSize.x, texelSize.y)).rgb;

  const vec3 luma=vec3(0.299,0.587,0.114);
  float lumaM =dot(rgbM, luma);
  float lumaNW=dot(rgbNW,luma);
  float lumaNE=dot(rgbNE,luma);
  float lumaSW=dot(rgbSW,luma);
  float lumaSE=dot(rgbSE,luma);

  float lumaMin=min(lumaM,min(min(lumaNW,lumaNE),min(lumaSW,lumaSE)));
  float lumaMax=max(lumaM,max(max(lumaNW,lumaNE),max(lumaSW,lumaSE)));

  float range=lumaMax-lumaMin;
  if(range<max(0.04,lumaMax*0.125)){
    return vec4(rgbM,1.0);
  }

  vec2 dir=vec2(
    -((lumaNW+lumaNE)-(lumaSW+lumaSE)),
    ((lumaNW+lumaSW)-(lumaNE+lumaSE))
  );
  float dirReduce=max((lumaNW+lumaNE+lumaSW+lumaSE)*0.03125,0.0078125);
  float rcpDirMin=1.0/(min(abs(dir.x),abs(dir.y))+dirReduce);
  dir=min(vec2(8.0),max(vec2(-8.0),dir*rcpDirMin))*texelSize;

  vec3 rgbA=0.5*(
    texture(tex,uv+dir*(1.0/3.0-0.5)).rgb+
    texture(tex,uv+dir*(2.0/3.0-0.5)).rgb
  );
  vec3 rgbB=rgbA*0.5+0.25*(
    texture(tex,uv+dir*-0.5).rgb+
    texture(tex,uv+dir* 0.5).rgb
  );
  float lumaB=dot(rgbB,luma);
  if((lumaB<lumaMin)||(lumaB>lumaMax)){
    return vec4(rgbA,1.0);
  }
  return vec4(rgbB,1.0);
}

void main(){
  vec4 rawSource=texture(uTex,vUv);
  bool isBackground=uSkyEnabled>0.5 && distance(rawSource.rgb,uClearColor)<0.004;
  vec4 source=isBackground?rawSource:applyFxaa(uTex,vUv);
  // Lens spectral dispersion (radial chromatic aberration towards viewport edges)
  if(!isBackground){
    vec2 centerOffset=vUv-vec2(0.5);
    float distSq=dot(centerOffset,centerOffset);
    if(distSq>0.04){
      vec2 chromaOffset=centerOffset*distSq*0.010;
      source.r=applyFxaa(uTex,vUv-chromaOffset).r;
      source.b=applyFxaa(uTex,vUv+chromaOffset).b;
    }
  }
  // The world pass clears untouched pixels to uClearColor. Replace only that
  // exact background, so the sky is always active without covering geometry.
  if(isBackground){
    vec3 viewDirection=worldDirectionForUv(vUv);
    vec3 worldDirection=normalize((uInverseView*vec4(viewDirection,0.0)).xyz);
    source.rgb=uSkyTextureEnabled>0.5
      ? equirectangularSky(vUv)
      : skyBackground(worldDirection);
    vec4 clouds=volumetricClouds(worldDirection);
    source.rgb=source.rgb* (1.0-clouds.a)+clouds.rgb;
  }
  // Exposure operates in scene-linear space; tone mapping prevents HDR
  // highlights from clipping before the selected output transfer function.
  vec3 color=max(source.rgb,vec3(0.))*max(uExposure,0.);
  vec3 mapped=uToneMap>3.0
    ?agxToneMap(color)
    :(uToneMap>1.5?acesToneMap(color):reinhardToneMap(color));
  float toneMix=uToneMap>3.0
    ?clamp((uToneMap-3.0)*2.0,0.,1.)
    :(uToneMap>1.5?clamp(uToneMap-1.5,0.,1.):clamp(uToneMap,0.,1.));
  color=mix(color,mapped,toneMix);
  float edge=distance(vUv,vec2(.5));
  float vignette=smoothstep(.35,.78,edge);
  color*=1.-clamp(uVignette,0.,1.)*vignette;
  if(uOutputEncoding>.5) color=linearToSrgb(max(color,vec3(0.)));
  // Atmospheric precipitation is submitted as depth-tested world geometry;
  // the present pass must never paint weather over unrelated surfaces.
  // A stable screen-space grain keeps captures reproducible for a fixed
  // viewport while still giving the dark gothic presentation a fine film
  // texture. It is deliberately tiny and never changes alpha.
  color+=((hash(gl_FragCoord.xy)-.5)*.06)*max(uGrain,0.);
  oColor=vec4(clamp(color,0.,1.),source.a);
}
''';

